import argparse,gzip,hashlib,json,subprocess
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument('--output',required=True);a=p.parse_args();ref=json.loads(gzip.decompress(Path('docs/heuristic-subsecond-reference.json.gz').read_bytes()));exe=Path('build/petri-comparison-checkpoint-build/Release/minera_export.exe');checks=[]
for i,r in enumerate(ref['observations']):
 x=Path(f'build/heuristic-subsecond-check-{i}.xes');x.write_text(r['xes'],encoding='utf-8');out=x.with_suffix('.json');cmd=[str(exe),str(x),'--heuristic-variant',r['variant'].lower(),'--heuristic-decoration','performance','--heuristic-start-timestamp-attribute','start_timestamp','-o',str(out)]
 if r['business']:cmd+=['--heuristic-business-hours']
 if 'business_hour_slots' in r['parameters']:cmd+=['--heuristic-business-hour-slots',','.join(f'{start}-{end}' for start,end in r['parameters']['business_hour_slots']) or 'none']
 row={'index':i,'name':r['name'],'expected':r['expected']}
 try:
  proc=subprocess.run(cmd,capture_output=True,text=True,timeout=30);row.update(exit_code=proc.returncode,stderr=proc.stderr)
  if proc.returncode==0:
   payload=json.loads(out.read_text());n=payload['heuristics_net'];names=n['activities'] if n['activity_ids_are_local'] else [v['name'] for v in payload['activities']]
   row['actual']={'wait':sorted([[[names[e['source']],names[e['target']]],e['mean_wait_seconds']] for e in n['relation_statistics'] if e['direct_adjacency_frequency']]),'sojourn':{names[e['activity']]:e['mean_sojourn_seconds'] for e in n['activity_statistics']} if r['variant']=='PLUSPLUS' else {},'edges':sorted([[names[e['source']],names[e['target']],e['dependency'],e['frequency'],e['representation']] for e in n['edges']])}
 except subprocess.TimeoutExpired:row['timeout']=True
 row['matched']=row.get('actual')==row['expected'];checks.append(row)
 if (i+1)%160==0:print(i+1,'cases checked',flush=True)
report={'checks':checks,'native_executable_sha256':hashlib.sha256(exe.read_bytes()).hexdigest()};Path(a.output).write_text(json.dumps(report,indent=2)+'\n',encoding='utf-8');print(sum(c['matched'] for c in checks),'/',len(checks));print('first mismatches:',[c['index'] for c in checks if not c['matched']][:25])

