import warnings
warnings.filterwarnings('ignore')
import gzip,json,sys
from datetime import datetime
from pathlib import Path
from xml.etree import ElementTree as ET
from pm4py.algo.discovery.heuristics import algorithm
from pm4py.objects.log.obj import EventLog,Trace,Event
ref=json.loads(gzip.decompress(Path('docs/heuristic-subsecond-reference.json.gz').read_bytes()))
checks=[]
for row in ref['observations']:
 traces=[]
 for trace in ET.fromstring(row['xes']).findall('trace'):
  events=[]
  for event in trace.findall('event'):
   fields={a.attrib['key']:a.attrib['value'] for a in event}
   for key in ['time:timestamp','start_timestamp']:
    if key in fields: fields[key]=datetime.fromisoformat(fields[key])
   events.append(Event(fields))
  traces.append(Trace(events))
 try:
  net=algorithm.apply_heu(EventLog(traces),parameters=row['parameters'],variant=getattr(algorithm.Variants,row['variant']))
  actual={'wait':sorted([[list(k),v] for k,v in net.performance_dfg.items()]),'sojourn':net.sojourn_times if row['variant']=='PLUSPLUS' else {},'edges':sorted([[a,b.node_name,e.dependency_value,e.dfg_value,e.repr_value] for a,node in net.nodes.items() for b,edges in node.output_connections.items() for e in edges])}
  checks.append({'name':row['name'],'matched':actual==row['expected'],'actual':actual})
 except Exception as exc:
  checks.append({'name':row['name'],'matched':False,'error_type':type(exc).__name__,'error':str(exc)})
Path('build/heuristic-subsecond-reference-replay.json').write_text(json.dumps({'checks':checks,'python':sys.version},indent=2)+'\n',encoding='utf-8')
print(sum(r['matched'] for r in checks),'/',len(checks),'public replay matches')
assert all(r['matched'] for r in checks)
